import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

softsign_cuda_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void softsign_kernel(const float* __restrict__ inp, float* __restrict__ out, int size) {
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    if (idx < size) {
        float val = inp[idx];
        out[idx] = val / (1.0f + fabsf(val));
    }
}

torch::Tensor softsign_cuda_forward(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int64_t size = x.numel();

    const int block_size = 256;
    const int grid_size = (size + block_size - 1) / block_size;

    softsign_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size
    );

    return out;
}
"""

softsign_cpp_source = r"""
torch::Tensor softsign_cuda_forward(torch::Tensor x);
"""

softsign_module = load_inline(
    name="softsign_module",
    cpp_sources=softsign_cpp_source,
    cuda_sources=softsign_cuda_source,
    functions=["softsign_cuda_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Simple model that performs a Softsign activation with a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return softsign_module.softsign_cuda_forward(x)

